import {courses} from './curriculum.js';
import {projects} from './projects.js';
import {courseRecord,emptyLearning,updateCourse,assessmentPassed,courseCheckpoint,parseLearning,prerequisiteOrder} from './learning-core.js';
import {networkScenarios,evaluateNetwork} from './network.js';
const $=id=>document.getElementById(id);
const el=(tag,text,className)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;};
const storageKey='devops-universe-courses-v1';
let state=emptyLearning(),current=courses[0],lessonIndex=0,host,storage=true;
try{state=parseLearning(localStorage.getItem(storageKey),courses,projects);}catch{storage=false;}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));storage=true;}catch{storage=false;}renderCourseStatus();renderRoadmap();}
function codeBlock(text){const wrapper=el('div');const header=el('div',undefined,'command-header');header.append(el('span','EXERCISE TEXT / COMMANDS — REVIEW BEFORE RUNNING'));const b=el('button','Copy','copy-command');b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text);b.textContent='Copied';}catch{b.textContent='Select and copy the text below';}});header.append(b);wrapper.append(header,el('pre',text,'command'));return wrapper;}
export function openTopic(titleOrId){const c=courses.find(c=>c.id===titleOrId||c.title===titleOrId);if(!c)return;host.showPage('study');loadCourse(c.id);$('course-name').setAttribute('tabindex','-1');$('course-name').focus({preventScroll:true});window.scrollTo({top:0});}
function renderCourseStatus(){const r=courseRecord(state,current.id);const passed=assessmentPassed(r,current);$('course-status').textContent=storage?`${r.read.length}/3 lessons read · ${passed?'assessment passed':'assessment pending'} · ${courseCheckpoint(state,current)?'checkpoint recorded':'practice '+(r.practice?'recorded':'pending')}`:'Storage unavailable · progress lasts this session';$('reading-progress').textContent=`${r.read.length} of 3 lessons marked read. Reading is not hands-on verification.`;}
function renderLessonTabs(){const r=courseRecord(state,current.id);$('course-lessons').replaceChildren(...current.lessons.map((l,i)=>{const b=el('button',undefined,'lesson-tab'+(lessonIndex===i?' active':''));b.append(el('small',`${r.read.includes(i)?'✓ ':''}${l.level.toUpperCase()}`),el('strong',l.title));b.setAttribute('aria-current',lessonIndex===i?'step':'false');b.addEventListener('click',()=>{lessonIndex=i;renderReading();});return b;}));}
function renderReading(){const l=current.lessons[lessonIndex];$('lesson-level').textContent=`${l.level.toUpperCase()} · LESSON ${lessonIndex+1} OF 3`;$('reading-title').textContent=l.title;$('reading-text').textContent=l.explanation;$('reading-check').textContent=l.check;$('mark-read').textContent=courseRecord(state,current.id).read.includes(lessonIndex)?'Read ✓ · Continue →':'Mark read and continue →';renderLessonTabs();renderCourseStatus();}
function renderAssessment(){const r=courseRecord(state,current.id);$('course-questions').replaceChildren(...current.questions.map((q,i)=>{const section=el('section',undefined,'assessment-question');section.append(el('h3',`${i+1}. ${q.prompt}`));const feedback=el('p',undefined,'assessment-feedback');feedback.setAttribute('role','status');q.options.forEach((text,j)=>{const selected=r.answers[i]===j;const b=el('button',text,'choice'+(selected?(j===q.correct?' correct':' wrong'):''));b.setAttribute('aria-pressed',String(selected));b.addEventListener('click',()=>{state=updateCourse(state,current.id,{answers:{...courseRecord(state,current.id).answers,[i]:j}});save();renderAssessment();});section.append(b);});if(r.answers[i]!==undefined){const good=r.answers[i]===q.correct;feedback.textContent=(good?'Correct. ':'Try again. ')+q.explanation;feedback.classList.add(good?'feedback-success':'feedback-error');}section.append(feedback);return section;}));const count=current.questions.filter((q,i)=>r.answers[i]===q.correct).length;$('assessment-summary').textContent=`${count}/${current.questions.length} correct. ${count===current.questions.length?'Knowledge checkpoint passed. Record actual practical observations separately.':'Review the explanation and retry when ready.'}`;}
function loadCourse(id){current=courses.find(c=>c.id===id)||courses[0];lessonIndex=0;$('course-select').value=current.id;$('course-name').textContent=current.title;$('course-area').textContent=current.area.toUpperCase();$('course-purpose').textContent=current.purpose;$('course-reference').href=current.reference;
 const prerequisites=$('course-prerequisites');prerequisites.replaceChildren(el('strong','HELPFUL PREREQUISITES'));if(!current.prerequisites.length)prerequisites.append(el('p','Start here. No previous topic is required.'));else current.prerequisites.forEach(id=>{const c=courses.find(c=>c.id===id);const b=el('button',`${courseCheckpoint(state,c)?'✓ ':''}${c.title} ↗`);b.addEventListener('click',()=>loadCourse(id));prerequisites.append(b);});prerequisites.append(el('p','Prerequisites guide you; topics remain open for direct study.'));
 $('lab-environment').textContent=current.lab.environment;$('practical-tasks').replaceChildren(...current.lab.tasks.map((t,i)=>{const section=el('article',undefined,'practical-task');section.append(el('h3',`${i+1}. ${t.title}`),codeBlock(t.command),el('p','Expected evidence: '+t.expected),el('p','Why: '+t.why));return section;}));$('lab-cleanup').textContent=current.lab.cleanup;const r=courseRecord(state,current.id);$('practice-evidence').value=r.evidence;$('practice-confirm').checked=r.practice;$('practice-feedback').textContent=r.practice?'Practice record saved (self-reported; external execution not independently verified).':'';$('challenge-title').textContent=current.challenge.symptom;$('challenge-evidence').textContent=current.challenge.evidence;$('challenge-hint').textContent=current.challenge.hint;$('challenge-solution').textContent=current.challenge.solution;document.querySelectorAll('.challenge-section details').forEach(d=>d.open=false);renderReading();renderAssessment();renderCourseResults();}
function renderCourseResults(){const q=$('course-search').value.trim().toLowerCase();const result=courses.filter(c=>[c.title,...c.tools,...c.skills].join(' ').toLowerCase().includes(q));$('course-results').replaceChildren(...result.map(c=>{const b=el('button',undefined,'course-result'+(c.id===current.id?' current':''));b.append(el('strong',c.title),el('small',`${c.area} · 3 lessons + practice + assessment`));b.addEventListener('click',()=>loadCourse(c.id));return b;}));$('course-no-results').hidden=result.length>0;}
export function renderRoadmap(){$('roadmap-list').replaceChildren(...prerequisiteOrder(courses).map((c,i)=>{const r=courseRecord(state,c.id);const b=el('button',undefined,'roadmap-course');b.append(el('strong',`${String(i+1).padStart(2,'0')}. ${c.title}`),el('small',`${r.read.length}/3 read · ${courseCheckpoint(state,c)?'checkpoint recorded':'continue learning'}`));b.addEventListener('click',()=>openTopic(c.id));return b;}));}
function renderNetwork(reset=false){const scenario=networkScenarios[$('network-scenario').value];if(reset)$('network-port').value=String(scenario.port);$('network-endpoints').textContent=`Example source ${scenario.source}:ephemeral → destination ${scenario.destination}:${$('network-port').value} · ${scenario.protocol}`;$('network-tls-label').hidden=!['internet-alb','app-api'].includes($('network-scenario').value);const result=evaluateNetwork({scenario:$('network-scenario').value,port:$('network-port').value,route:$('network-route').checked,nacl:$('network-nacl').checked,rule:$('network-rule').checked,listener:$('network-listener').checked,tls:$('network-tls').checked});const root=$('network-decision');root.replaceChildren(el('p',result.summary,result.ok?'feedback-success':'feedback-error'));result.steps.forEach(s=>{const row=el('div',undefined,'decision-row');const text=el('div');text.append(el('strong',s.name),el('p',s.detail));row.append(el('span',s.state.toUpperCase(),'decision-state '+s.state.replaceAll(' ','-')),text);root.append(row);});if(result.returnPath)root.append(el('p','Return path: '+result.returnPath));root.append(el('p','Simplification: checks use an explanatory order, not a trace of cloud internals. A failure here is a modeled decision, not a guaranteed real timeout/reject. DNS, host firewalls, MTU, provider routing details and application permissions require additional checks in real systems.'));}
function renderProjects(){$('project-list').replaceChildren(...projects.map(p=>{const card=el('article',undefined,'project-card');card.append(el('div',p.level.toUpperCase(),'eyebrow'),el('h2',p.title),el('p',p.goal),el('p',p.environment));const prereq=el('div',undefined,'project-prerequisites');p.prerequisites.forEach(id=>{const c=courses.find(c=>c.id===id);const b=el('button',c.title+' ↗');b.addEventListener('click',()=>openTopic(id));prereq.append(b);});card.append(prereq);const files=el('div',undefined,'project-files');p.files.forEach(name=>{const a=el('a',name+' ↓');a.href='./projects/learning-app/'+name;a.download=name;files.append(a);});card.append(files);
 p.milestones.forEach((m,i)=>{const r=state.projects[p.id]?.[i]||{evidence:'',done:false};const details=el('details',undefined,'milestone');details.open=i===0;const summary=el('summary',`${r.done?'✓ ':''}${i+1}. ${m.title}`);details.append(summary,el('p',m.instructions),codeBlock(m.commands),el('p','Expected result: '+m.expected),el('p','Record evidence: '+m.verification));const label=el('label','Your actual observations (minimum 80 characters)');const textarea=el('textarea');textarea.rows=4;textarea.maxLength=5000;textarea.value=r.evidence;textarea.setAttribute('aria-label',`${p.title}: ${m.title} evidence`);const b=el('button','Record milestone (self-reported)','outline');const feedback=el('p',r.done?'Saved as self-reported practice; not independently verified.':'','small-status');feedback.setAttribute('role','status');b.addEventListener('click',()=>{if(textarea.value.trim().length<80){feedback.textContent='Add at least 80 characters describing commands, actual output, what it proves and a limitation.';return;}state={...state,projects:{...state.projects,[p.id]:{...state.projects[p.id],[i]:{evidence:textarea.value.slice(0,5000),done:true}}}};save();summary.textContent=`✓ ${i+1}. ${m.title}`;feedback.textContent='Saved as self-reported practice; not independently verified.';});details.append(label,textarea,b,feedback);card.append(details);});card.append(el('div','Scope: '+p.limits,'scope-note'));const cleanup=el('details');cleanup.append(el('summary','Cleanup this project'),codeBlock(p.cleanup));card.append(cleanup);return card;}));}
export function initializeStudy(api){host=api;$('course-select').replaceChildren(...courses.map(c=>{const option=el('option',`${c.title} · ${c.area}`);option.value=c.id;return option;}));$('course-select').addEventListener('change',()=>loadCourse($('course-select').value));$('course-search').addEventListener('input',renderCourseResults);$('mark-read').addEventListener('click',()=>{const r=courseRecord(state,current.id);state=updateCourse(state,current.id,{read:[...new Set([...r.read,lessonIndex])]});save();if(lessonIndex<current.lessons.length-1)lessonIndex++;renderReading();});$('course-model').addEventListener('click',()=>host.openLab(current.related));$('save-practice').addEventListener('click',()=>{const evidence=$('practice-evidence').value.slice(0,5000);const confirmed=$('practice-confirm').checked;state=updateCourse(state,current.id,{evidence,practice:confirmed&&evidence.trim().length>=80});save();$('practice-feedback').textContent=confirmed&&evidence.trim().length>=80?'Saved as self-reported practice. External execution is not independently verified.':'Notes saved. To record completion, add at least 80 characters of actual observations and confirm you performed the exercise.';});$('next-course').addEventListener('click',()=>{const ordered=prerequisiteOrder(courses);const i=ordered.findIndex(c=>c.id===current.id);loadCourse(ordered[Math.min(i+1,ordered.length-1)].id);window.scrollTo({top:0});});$('network-scenario').replaceChildren(...Object.entries(networkScenarios).map(([id,s])=>{const o=el('option',s.title);o.value=id;return o;}));$('network-scenario').value='alb-app';for(const id of ['network-route','network-nacl','network-rule','network-listener','network-tls'])$(id).checked=true;$('network-scenario').addEventListener('change',()=>renderNetwork(true));$('evaluate-network').addEventListener('click',()=>renderNetwork());
 loadCourse(courses[0].id);renderNetwork(true);renderRoadmap();renderProjects();
}

export function learningProgressReport(){return {...state,summary:courses.map(c=>({topic:c.title,checkpoint:courseCheckpoint(state,c),assessment:assessmentPassed(courseRecord(state,c.id),c),practiceSelfReported:courseRecord(state,c.id).practice}))};}
export function resetLearning(){state=emptyLearning();save();loadCourse(current.id);renderProjects();}
